CREATE COLUMN TABLE "TEST_AP"."WKO1" ("OrderNum" INTEGER CS_INT NOT NULL , "LineID" INTEGER CS_INT DEFAULT 0 NOT NULL , "ItemCode" NVARCHAR(50), "Descript" NVARCHAR(100), "Quantity" DECIMAL(21,6) CS_FIXED, "Price" DECIMAL(21,6) CS_FIXED, "Currency" NVARCHAR(3), "WhsCode" NVARCHAR(8), "FinncPriod" INTEGER CS_INT, "ActWorkCod" NVARCHAR(15), "ActWorkSum" DECIMAL(21,6) CS_FIXED, "ProdUpgNum" INTEGER CS_INT, PRIMARY KEY ("OrderNum", "LineID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "WKO1_CURRENCY" ON "TEST_AP"."WKO1" ( "Currency" ASC )